/* Rattil service worker — generated by scripts/generate-sw.mjs from scripts/sw-template.js. */
/* eslint-disable */
const VERSION = "__VERSION__";
const CORE = __CORE__;
const REST = __REST__;
const CACHE = "rattil-" + VERSION;
// Surah and Mushaf-page routes are precached for the locale the user reads in.
let locale = "ar";
let ALL = CORE.concat(REST.ar);
let progress = { type: "precache-progress", done: 0, total: ALL.length, complete: false, locale };
let filling = null;

function setLocale(l) {
  if ((l !== "ar" && l !== "en") || l === locale) return;
  locale = l;
  ALL = CORE.concat(REST[l]);
  progress = { type: "precache-progress", done: 0, total: ALL.length, complete: false, locale };
}

async function broadcast() {
  const clients = await self.clients.matchAll({ includeUncontrolled: true });
  for (const c of clients) c.postMessage(progress);
}

async function cacheList(cache, urls, concurrency, onEach) {
  let i = 0;
  async function worker() {
    while (i < urls.length) {
      const u = urls[i++];
      try {
        const res = await fetch(u, { cache: "no-cache" });
        if (res.ok) await cache.put(u, res);
        else throw new Error(u + " " + res.status);
      } catch (e) {
        if (!onEach) throw e;
      }
      if (onEach) onEach();
    }
  }
  await Promise.all(Array.from({ length: concurrency }, worker));
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      await cacheList(cache, CORE, 8, null);
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      for (const k of await caches.keys()) if (k !== CACHE && k.startsWith("rattil-")) await caches.delete(k);
      await self.clients.claim();
    })(),
  );
});

async function cachedPaths(cache) {
  return new Set((await cache.keys()).map((r) => new URL(r.url).pathname));
}

function fillAll() {
  if (filling) return filling;
  filling = (async () => {
    const cache = await caches.open(CACHE);
    const have = await cachedPaths(cache);
    const todo = ALL.filter((u) => !have.has(u));
    progress.done = ALL.length - todo.length;
    await broadcast();
    let n = 0;
    await cacheList(cache, todo, 6, () => {
      progress.done++;
      if (++n % 40 === 0) broadcast();
    });
    const after = await cachedPaths(cache);
    const missing = ALL.filter((u) => !after.has(u)).length;
    progress.done = ALL.length - missing;
    progress.complete = missing === 0;
    await broadcast();
  })().finally(() => {
    filling = null;
  });
  return filling;
}

self.addEventListener("message", (event) => {
  const data = event.data || {};
  if (data.type === "precache-all") {
    setLocale(data.locale);
    if (progress.complete) broadcast();
    else event.waitUntil(fillAll());
  }
});

function cacheKey(req, url) {
  let path = url.pathname;
  const isDoc = req.mode === "navigate" || req.destination === "document";
  if (isDoc && !path.endsWith("/") && !/\.[a-z0-9]+$/i.test(path)) path += "/";
  return path;
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      const key = cacheKey(req, url);
      const hit = await cache.match(key, { ignoreSearch: true, ignoreVary: true });
      if (hit) return hit;
      try {
        const res = await fetch(req);
        if (res.ok && res.type === "basic" && !res.redirected) cache.put(key, res.clone());
        return res;
      } catch (err) {
        if (req.mode === "navigate") {
          const fallback = (await cache.match("__BASE__/404.html")) || (await cache.match("__BASE__/"));
          if (fallback) return fallback;
        }
        return new Response("Offline", { status: 503, headers: { "Content-Type": "text/plain" } });
      }
    })(),
  );
});
